function useReducedMotion() {
  const [reduced, setReduced] = useState(true);
  useEffect(() => {
    let active = true;
    void AccessibilityInfo.isReduceMotionEnabled().then(value => { if (active) setReduced(value); });
    const listener = AccessibilityInfo.addEventListener('reduceMotionChanged', setReduced);
    return () => { active = false; listener.remove(); };
  }, []);
  return reduced;
}

function AnimatedPage({ children, fill = true }: { children: React.ReactNode; fill?: boolean }) {
  const progress = useRef(new Animated.Value(1)).current;
  const reduced = useReducedMotion();
  useEffect(() => {
    if (reduced) { progress.setValue(1); return; }
    progress.setValue(0);
    const animation = Animated.timing(progress, { toValue: 1, duration: 280, easing: Easing.out(Easing.cubic), useNativeDriver: true });
    animation.start();
    return () => animation.stop();
  }, [progress, reduced]);
  return <Animated.View style={{ flex: fill ? 1 : undefined, gap: 20, opacity: progress, transform: [{ translateY: progress.interpolate({ inputRange: [0, 1], outputRange: [10, 0] }) }] }}>{children}</Animated.View>;
}

function AppHeader() {
  const { colors, isDark, toggleTheme } = useTheme();
  const styles = useAppStyles();
  return <View style={styles.appHeader}>
    <View style={styles.headerBrand}><View style={styles.headerMark}><Feather name="check" size={22} color={colors.onPrimary} /></View><Text style={styles.headerName}>PicTask<Text style={{ color: colors.primary }}>.</Text></Text></View>
    <Pressable accessibilityRole="button" accessibilityLabel={isDark ? 'Switch to light mode' : 'Switch to dark mode'} accessibilityHint="Changes the appearance of the entire app" onPress={toggleTheme} style={({ pressed }) => [styles.themeToggle, pressed && styles.buttonPressed]}>
      <Feather name={isDark ? 'sun' : 'moon'} size={21} color={colors.primaryDark} />
    </Pressable>
  </View>;
}

const tabs: Array<{ id: AppTab; icon: ComponentProps<typeof Feather>['name']; label: string }> = [
  { id: 'home', icon: 'home', label: 'Home' }, { id: 'calendar', icon: 'calendar', label: 'Calendar' },
  { id: 'scan', icon: 'plus', label: 'Scan' }, { id: 'vault', icon: 'shield', label: 'Vault' }, { id: 'profile', icon: 'user', label: 'Profile' },
];
const dayLabel = (date?: string) => date ? new Intl.DateTimeFormat('en-PH', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(`${date}T12:00:00`)) : 'No due date';
const peso = (value?: number) => value === undefined ? 'Amount not detected' : value.toLocaleString('en-PH', { style: 'currency', currency: 'PHP' });
const nowIso = () => new Date().toISOString();

function Button({ label, onPress, kind = 'primary', disabled = false }: { label: string; onPress: () => void; kind?: 'primary' | 'secondary' | 'danger'; disabled?: boolean }) {
  const { colors, layout } = useTheme();
  const styles = useAppStyles();
  const scale = useRef(new Animated.Value(1)).current;
  const reduced = useReducedMotion();
  const animatePress = (toValue: number) => {
    Animated.spring(scale, { toValue, speed: 35, bounciness: 3, useNativeDriver: true }).start();
  };
  const style = kind === 'primary' ? layout.button : kind === 'secondary' ? layout.secondaryButton : styles.dangerButton;
  const textStyle = kind === 'primary' ? layout.buttonText : kind === 'secondary' ? layout.secondaryButtonText : [layout.buttonText, { color: colors.white }];
  return <Animated.View style={{ transform: [{ scale }] }}><Pressable accessibilityRole="button" accessibilityState={{ disabled, busy: disabled }} disabled={disabled} onPressIn={() => { if (!reduced) animatePress(0.975); }} onPressOut={() => animatePress(1)} onPress={onPress} style={({ pressed }) => [style, disabled && styles.disabled, pressed && { opacity: 0.85 }]}><Text style={textStyle}>{label}</Text>{kind === "primary" ? <Feather name="arrow-right" size={18} color={colors.onPrimary} /> : null}</Pressable></Animated.View>;
}
function Card({ children, style }: { children: React.ReactNode; style?: object }) { const { layout } = useTheme(); return <View style={[layout.card, style]}>{children}</View>; }
function Pill({ text, tone = 'neutral' }: { text: string; tone?: 'neutral' | 'success' | 'warning' | 'blue' }) {
  const { colors } = useTheme();
  const styles = useAppStyles();
  const background = tone === 'success' ? colors.successSurface : tone === 'warning' ? colors.warningSurface : tone === 'blue' ? colors.blueSurface : colors.surfaceMuted;
  const foreground = tone === 'success' ? colors.success : tone === 'warning' ? colors.warning : tone === 'blue' ? colors.primary : colors.textMuted;
  return <View style={[styles.pill, { backgroundColor: background }]}><Text style={[styles.pillText, { color: foreground }]}>{text}</Text></View>;
}

function AuthScreen({ onPreview }: { onPreview: () => void }) {
  const { colors, layout, isDark } = useTheme();
  const styles = useAppStyles();
  const [email, setEmail] = useState(''); const [password, setPassword] = useState('');
  const [mode, setMode] = useState<'signIn' | 'signUp'>('signIn'); const [busy, setBusy] = useState(false); const [message, setMessage] = useState('');
  const [messageIsError, setMessageIsError] = useState(false);
  const configured = Boolean(supabase);
  const submit = async () => {
    if (!supabase) return;
    if (!email.trim() || password.length < 8) { setMessageIsError(true); setMessage('Use a valid email and a password with at least 8 characters.'); return; }
    setBusy(true); setMessage(''); setMessageIsError(false);
    const response = mode === 'signIn' ? await supabase.auth.signInWithPassword({ email: email.trim(), password }) : await supabase.auth.signUp({ email: email.trim(), password });
    setBusy(false); setMessageIsError(Boolean(response.error)); setMessage(response.error ? response.error.message : mode === 'signUp' ? 'Check your email to confirm your account, then sign in.' : 'Signed in.');
  };
  return <KeyboardAvoidingView style={layout.screen} behavior={Platform.select({ ios: 'padding', default: undefined })}><StatusBar barStyle={isDark ? "light-content" : "dark-content"} />
    <SafeAreaView style={layout.screen} edges={["top", "left", "right", "bottom"]}><AppHeader /><ScrollView contentContainerStyle={styles.authContent} keyboardShouldPersistTaps="handled">
      <AnimatedPage fill={false}>
      <View style={styles.authHero}>
        <Text accessibilityRole="header" style={styles.welcomeHeadline}>Less paperwork.{"\n"}<Text style={{ color: colors.primary }}>More peace of mind.</Text></Text>
        <Text style={styles.authWelcomeText}>Complete tasks one step at a time.</Text>
      </View>
      
      <Card style={styles.authCard}><Text style={[styles.authCardTitle, styles.authCardTitleUncentered]}>{configured ? (mode === 'signIn' ? 'Welcome back' : 'Get started') : 'Your next step starts here'}</Text><Text style={[layout.subtitle, styles.authSubtitleUncentered]}>{configured ? (mode === 'signIn' ? 'Sign-in and continue where you left off.' : 'Create your account and take the first step.') : 'Explore a calmer way to keep track of your tasks.'}</Text>
        {configured ? <><Text style={layout.label}>Email address</Text><TextInput keyboardAppearance={isDark ? "dark" : "light"} accessibilityLabel="Email address" autoComplete="email" style={layout.input} autoCapitalize="none" keyboardType="email-address" placeholder="Email address" placeholderTextColor={colors.textMuted} value={email} onChangeText={setEmail} /><Text style={layout.label}>Password</Text><TextInput keyboardAppearance={isDark ? "dark" : "light"} accessibilityLabel="Password" autoComplete={mode === "signIn" ? "current-password" : "new-password"} style={layout.input} secureTextEntry placeholder="Password" placeholderTextColor={colors.textMuted} value={password} onChangeText={setPassword} />{message ? <Text style={[styles.message, styles.messageUncentered, messageIsError && { color: colors.danger }]}>{message}</Text> : null}<Button label={busy ? 'Please wait…' : mode === 'signIn' ? 'Sign in' : 'Create account'} onPress={submit} disabled={busy} /><Pressable onPress={() => { setMode(mode === 'signIn' ? 'signUp' : 'signIn'); setMessage(''); }}><Text style={styles.link}>{mode === 'signIn' ? 'Need an account? Sign up' : 'Already have an account? Sign in'}</Text></Pressable></> : <><Text style={[styles.message, styles.messageUncentered]}>Try the local preview. Your documents stay on this device.</Text><Button label="Open local preview" onPress={onPreview} /></>}
      </Card><View style={styles.privacyRow}><Feather name="shield" size={16} color={colors.textMuted} /><Text style={styles.privacyCopy}>Private by design. Always in your control.</Text></View></AnimatedPage>
    </ScrollView></SafeAreaView></KeyboardAvoidingView>;
}

function CalendarGrid({ tasks, selectedDate, onSelect }: { tasks: TaskRecord[]; selectedDate: string; onSelect: (value: string) => void }) {
  const { colors, layout } = useTheme();
  const styles = useAppStyles();
  const [cursor, setCursor] = useState(() => new Date(`${selectedDate}T12:00:00`)); const year = cursor.getFullYear(); const month = cursor.getMonth();
  const first = new Date(year, month, 1).getDay(); const total = new Date(year, month + 1, 0).getDate(); const activeDates = new Set(tasks.filter((task) => !task.completed && task.dueDate).map((task) => task.dueDate));
  const cells = Array.from({ length: first + total }, (_, index) => index < first ? null : index - first + 1);
  return <Card><View style={styles.calendarHeader}><Pressable accessibilityRole="button" accessibilityLabel="Previous month" style={styles.calendarArrow} onPress={() => setCursor(new Date(year, month - 1, 1))}><Feather name="chevron-left" size={24} color={colors.primary} /></Pressable><Text style={layout.heading}>{cursor.toLocaleString('en-PH', { month: 'long', year: 'numeric' })}</Text><Pressable accessibilityRole="button" accessibilityLabel="Next month" style={styles.calendarArrow} onPress={() => setCursor(new Date(year, month + 1, 1))}><Feather name="chevron-right" size={24} color={colors.primary} /></Pressable></View><View style={styles.weekRow}>{['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((day, index) => <Text style={styles.weekday} key={`${day}-${index}`}>{day}</Text>)}</View><View style={styles.calendarGrid}>{cells.map((day, index) => {
    if (!day) return <View key={`blank-${index}`} style={styles.dayCell} />; const value = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`; const selected = value === selectedDate;
    return <Pressable key={value} onPress={() => onSelect(value)} style={[styles.dayCell, selected && styles.selectedDay]}><Text style={[styles.dayText, selected && styles.selectedDayText]}>{day}</Text>{activeDates.has(value) ? <View style={[styles.dayDot, selected && styles.selectedDot]} /> : null}</Pressable>;
  })}</View></Card>;
}

function TaskRow({ task, onToggle, onEdit, compact = false }: { task: TaskRecord; onToggle: () => void; onEdit?: () => void; compact?: boolean }) {
  const { colors } = useTheme();
  const styles = useAppStyles();
  return <View style={[styles.taskRow, task.completed && styles.completedRow]}><Pressable accessibilityRole="checkbox" accessibilityLabel={task.title} hitSlop={6} accessibilityState={{ checked: task.completed }} onPress={onToggle} style={[styles.check, task.completed && styles.checked]}>{task.completed ? <Feather name="check" size={17} color={colors.onPrimary} /> : null}</Pressable><View style={styles.taskText}><Text style={[styles.taskTitle, task.completed && styles.completedText]}>{task.title}</Text>{!compact ? <Text style={styles.taskMeta}>{dayLabel(task.dueDate)} · {task.syncState === 'synced' ? 'Synced' : task.syncState === 'local' ? 'Local preview' : 'Waiting to sync'}</Text> : null}</View>{onEdit ? <Pressable onPress={onEdit}><Text style={styles.rowAction}>Edit</Text></Pressable> : null}</View>;
}

function App() {
  const insets = useSafeAreaInsets();
  const reducedMotion = useReducedMotion();
  const { colors, layout, isDark } = useTheme();
  const styles = useAppStyles();
  const [user, setUser] = useState<AppUser | null>(null); const [ready, setReady] = useState(false); const [tab, setTab] = useState<AppTab>('home');
  const [documents, setDocuments] = useState<DocumentRecord[]>([]); const [tasks, setTasks] = useState<TaskRecord[]>([]); const [selectedDate, setSelectedDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [biometricEnabled, setBiometricEnabled] = useState(false); const [syncing, setSyncing] = useState(false); const [review, setReview] = useState<ScanReviewInput | null>(null); const [reviewTasks, setReviewTasks] = useState<TaskRecord[]>([]); const [editTask, setEditTask] = useState<TaskRecord | null>(null); const [newTaskTitle, setNewTaskTitle] = useState('');
  const [screenOwnerId, setScreenOwnerId] = useState<string | null>(null);

  // Reset before rendering a new session so a previous screen or modal cannot flash.
  const ownerId = user?.id ?? null;
  if (screenOwnerId !== ownerId) {
    setScreenOwnerId(ownerId);
    setTab('home');
    setReview(null);
    setReviewTasks([]);
    setEditTask(null);
    setNewTaskTitle('');
  }

  useEffect(() => { let active = true; let unsubscribe: (() => void) | undefined; void (async () => { const saved = await SecureStore.getItemAsync('pictask.biometric'); if (active) setBiometricEnabled(saved === 'true'); if (supabase) { const { data } = await supabase.auth.getSession(); if (active && data.session?.user) setUser({ id: data.session.user.id, email: data.session.user.email ?? 'Account', preview: false }); const listener = supabase.auth.onAuthStateChange((_event, session) => { if (active) setUser(session?.user ? { id: session.user.id, email: session.user.email ?? 'Account', preview: false } : null); }); unsubscribe = () => listener.data.subscription.unsubscribe(); } if (active) setReady(true); })(); return () => { active = false; unsubscribe?.(); }; }, []);

  const flushPending = async (ownerId: string) => { if (!supabase) return; for (const mutation of await loadMutations(ownerId)) { try { if (mutation.operation === 'upsert' && mutation.entity === 'document') await syncDocument(JSON.parse(mutation.payload) as DocumentRecord); if (mutation.operation === 'upsert' && mutation.entity === 'task') await syncTask(JSON.parse(mutation.payload) as TaskRecord); if (mutation.operation === 'delete' && mutation.entity === 'task') await deleteRemoteTask(JSON.parse(mutation.payload).id); await removeMutation(mutation.id); } catch { break; } } };
  const loadRecords = async (ownerId: string, preview: boolean) => { const local = await loadLocalRecords(ownerId); setDocuments(local.documents); setTasks(local.tasks); if (!preview && supabase) try { await flushPending(ownerId); const remote = await fetchRemoteRecords(ownerId); if (remote) { setDocuments(remote.documents); setTasks(remote.tasks); await Promise.all(remote.documents.map(saveLocalDocument)); await Promise.all(remote.tasks.map(saveLocalTask)); } } catch { /* local cache stays available offline */ } };
  useEffect(() => { if (user) void loadRecords(user.id, user.preview); else { setDocuments([]); setTasks([]); } }, [user?.id]);
  useEffect(() => {
    const listener = NetInfo.addEventListener((state) => { if (state.isConnected && user && !user.preview) void flushPending(user.id); });
    return () => listener();
  }, [user?.id]);
  const persistDocument = async (record: DocumentRecord) => { await saveLocalDocument(record); if (!user || user.preview || !supabase) return { ...record, syncState: 'local' as const }; try { const remote = await syncDocument(record); return { ...remote, syncState: 'synced' as const }; } catch { await queueMutation({ id: createId('mutation'), ownerId: record.ownerId, entity: 'document', operation: 'upsert', payload: JSON.stringify(record), localTimestamp: nowIso(), retryCount: 0 }); return { ...record, syncState: 'failed' as const }; } };
  const persistTask = async (record: TaskRecord) => { await saveLocalTask(record); if (!user || user.preview || !supabase) return { ...record, syncState: 'local' as const }; try { await syncTask(record); return { ...record, syncState: 'synced' as const }; } catch { await queueMutation({ id: createId('mutation'), ownerId: record.ownerId, entity: 'task', operation: 'upsert', payload: JSON.stringify(record), localTimestamp: nowIso(), retryCount: 0 }); return { ...record, syncState: 'failed' as const }; } };
  const syncAll = async () => { if (!user || user.preview || !supabase) return; setSyncing(true); await Promise.all(documents.map(async (record) => { const saved = await persistDocument({ ...record, syncState: 'pending' }); setDocuments((all) => all.map((item) => item.id === record.id ? saved : item)); })); await Promise.all(tasks.map(async (record) => { const saved = await persistTask({ ...record, syncState: 'pending' }); setTasks((all) => all.map((item) => item.id === record.id ? saved : item)); })); setSyncing(false); };
  const openVault = async () => { if (biometricEnabled && await LocalAuthentication.hasHardwareAsync()) { const result = await LocalAuthentication.authenticateAsync({ promptMessage: 'Unlock your PicTask Vault', disableDeviceFallback: false }); if (!result.success) return; } setTab('vault'); };
  const changeTab = (next: AppTab) => { if (next === 'vault') void openVault(); else setTab(next); };
  const startManual = () => { const input: ScanReviewInput = { sourceType: 'manual', category: 'general', confidence: 'manual', retention: 'details_only', details: { title: 'New task', provider: '', retainFullIdentifier: false } }; setReview(input); setReviewTasks([]); };
  const scanImage = async (mode: 'camera' | 'photo') => { const permission = mode === 'camera' ? await ImagePicker.requestCameraPermissionsAsync() : await ImagePicker.requestMediaLibraryPermissionsAsync(); if (!permission.granted) { Alert.alert('Permission needed', `Please allow ${mode === 'camera' ? 'camera' : 'photo'} access to scan a document you choose.`); return; } const result = mode === 'camera' ? await ImagePicker.launchCameraAsync({ mediaTypes: ['images'], quality: 0.85 }) : await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], quality: 0.85 }); if (result.canceled) return; const uri = result.assets[0].uri; try { const recognized = await TextRecognition.recognize(uri); const draft = extractReview(recognized.text, uri, mode === 'camera' ? 'scan' : 'photo'); setReview(draft); setReviewTasks(makeTasks(user?.id ?? 'local-user', 'draft', draft.category, draft.details.dueDate, draft.details.amountDue)); } catch { const draft = extractReview('', uri, mode === 'camera' ? 'scan' : 'photo'); draft.confidence = 'low'; setReview(draft); setReviewTasks(makeTasks(user?.id ?? 'local-user', 'draft', draft.category)); Alert.alert('Review required', 'Text could not be read automatically. You can enter details manually. OCR requires an Android development build.'); } };
  const updateReview = (change: Partial<ScanReviewInput['details']>) => setReview((current) => current ? { ...current, details: { ...current.details, ...change } } : current);
  const changeCategory = (category: DocumentCategory) => { setReview((current) => current ? { ...current, category } : current); setReviewTasks((current) => current.map((task, index) => ({ ...task, title: recommendedTaskTitles(category, review?.details.amountDue)[index] ?? task.title, recommendationSource: category === 'bill' ? 'bill_rule' : category === 'deadline' ? 'deadline_rule' : 'general_rule' }))); };
  const addDraftTask = () => { if (!newTaskTitle.trim() || !user) return; setReviewTasks((current) => [...current, { id: createId('task'), ownerId: user.id, documentId: 'draft', position: current.length, title: newTaskTitle.trim(), dueDate: review?.details.dueDate, completed: false, recommendationSource: 'manual', reminderDays: [7, 3, 1], syncState: 'pending', createdAt: nowIso(), updatedAt: nowIso() }]); setNewTaskTitle(''); };
  const saveReview = async () => { if (!review || !user) return; const id = createId('document'); const timestamp = nowIso(); const cleanDetails = { ...review.details }; delete cleanDetails.rawText; if (cleanDetails.accountNumber && !cleanDetails.retainFullIdentifier) cleanDetails.accountNumber = cleanDetails.accountNumber.slice(-4); const document: DocumentRecord = { id, ownerId: user.id, sourceType: review.sourceType, category: review.category, details: cleanDetails, retention: review.retention, sourceUri: review.retention === 'image_and_details' ? review.sourceUri : undefined, status: 'active', syncState: user.preview ? 'local' : 'pending', createdAt: timestamp, updatedAt: timestamp }; const nextTasks = reviewTasks.map((task, position) => ({ ...task, documentId: id, ownerId: user.id, position, dueDate: task.dueDate ?? document.details.dueDate, updatedAt: timestamp })); const savedDocument = await persistDocument(document); const savedTasks = await Promise.all(nextTasks.map(persistTask)); setDocuments((all) => [savedDocument, ...all]); setTasks((all) => [...all, ...savedTasks]); for (const task of savedTasks) void scheduleTaskReminders(task); if (review.sourceUri && review.retention !== 'image_and_details') try { await FileSystem.deleteAsync(review.sourceUri, { idempotent: true }); } catch { /* gallery provider may own the original */ } setReview(null); setReviewTasks([]); setTab('home'); };
  const toggleTask = async (task: TaskRecord) => { const next = { ...task, completed: !task.completed, updatedAt: nowIso(), syncState: user?.preview ? 'local' as const : 'pending' as const }; const saved = await persistTask(next); setTasks((all) => all.map((item) => item.id === task.id ? saved : item)); };
  const saveEditedTask = async () => { if (!editTask) return; const saved = await persistTask({ ...editTask, updatedAt: nowIso(), syncState: user?.preview ? 'local' : 'pending' }); setTasks((all) => all.map((item) => item.id === saved.id ? saved : item)); setEditTask(null); if (!saved.completed) void scheduleTaskReminders(saved); };
  const deleteTask = async (task: TaskRecord) => { await removeLocalTask(task.id); setTasks((all) => all.filter((item) => item.id !== task.id)); setEditTask(null); if (!user || user.preview || !supabase) return; try { await deleteRemoteTask(task.id); } catch { await queueMutation({ id: createId('mutation'), ownerId: task.ownerId, entity: 'task', operation: 'delete', payload: JSON.stringify({ id: task.id }), localTimestamp: nowIso(), retryCount: 0 }); } };
  const archiveDocument = async (document: DocumentRecord) => { const saved = await persistDocument({ ...document, status: 'archived' as DocumentStatus, archivedAt: nowIso(), updatedAt: nowIso(), syncState: user?.preview ? 'local' : 'pending' }); setDocuments((all) => all.map((item) => item.id === saved.id ? saved : item)); };
  const restoreDocument = async (document: DocumentRecord) => { const saved = await persistDocument({ ...document, status: 'active' as DocumentStatus, archivedAt: undefined, updatedAt: nowIso(), syncState: user?.preview ? 'local' : 'pending' }); setDocuments((all) => all.map((item) => item.id === saved.id ? saved : item)); };
  const activeDocuments = documents.filter((document) => document.status === 'active'); const activeTasks = tasks.filter((task) => activeDocuments.some((document) => document.id === task.documentId)); const sortByDeadline = (a: TaskRecord, b: TaskRecord) => Number(a.completed) - Number(b.completed) || (a.dueDate ?? '9999').localeCompare(b.dueDate ?? '9999'); const nextTasks = [...activeTasks].filter((task) => !task.completed).sort(sortByDeadline); const tasksForSelectedDay = activeTasks.filter((task) => task.dueDate === selectedDate).sort(sortByDeadline); const readyToArchive = activeDocuments.filter((document) => { const documentTasks = tasks.filter((task) => task.documentId === document.id); return documentTasks.length > 0 && documentTasks.every((task) => task.completed); });
  const toggleBiometric = async (next: boolean) => { if (next) { if (!(await LocalAuthentication.hasHardwareAsync())) { Alert.alert('Not available', 'This device does not offer biometric or device-credential authentication.'); return; } const result = await LocalAuthentication.authenticateAsync({ promptMessage: 'Confirm Vault protection', disableDeviceFallback: false }); if (!result.success) return; } setBiometricEnabled(next); await SecureStore.setItemAsync('pictask.biometric', String(next)); };
  const exportData = async () => { await Share.share({ title: 'PicTask export', message: JSON.stringify({ exportedAt: nowIso(), documents, tasks }, null, 2) }); };
  const resetPassword = async () => { if (!supabase || !user || user.preview) return; const { error } = await supabase.auth.resetPasswordForEmail(user.email); Alert.alert(error ? 'Could not send email' : 'Email sent', error?.message ?? 'Check your inbox for password-reset instructions.'); };
  const deleteAccount = () => Alert.alert('Delete account?', 'This permanently removes your app records, optional vault images, and local cache.', [{ text: 'Cancel', style: 'cancel' }, { text: 'Delete', style: 'destructive', onPress: () => { void (async () => { if (!user) return; await removeLocalRecords(user.id); if (supabase && !user.preview) { await supabase.functions.invoke('delete-account'); await supabase.auth.signOut(); } setUser(null); })(); } }]);
  const signOut = async () => { if (supabase && !user?.preview) await supabase.auth.signOut(); setUser(null); };
  if (!ready) return <View style={[layout.screen, styles.loader]}><ActivityIndicator color={colors.primary} /></View>;
  if (!user) return <AuthScreen onPreview={() => setUser({ id: 'local-preview', email: 'Local preview', preview: true })} />;

  const renderHome = () => <ScrollView contentContainerStyle={layout.content}><View style={styles.homeIntro}><Text style={styles.heroEyebrow}>{new Intl.DateTimeFormat('en-PH', { weekday: 'long', month: 'short', day: 'numeric' }).format(new Date()).toUpperCase()}</Text><Text accessibilityRole="header" style={layout.title}>Make room for today.</Text><Text style={layout.subtitle}>One clear step at a time. You�ve got this.</Text></View><View style={styles.statsRow}><Card style={styles.statCard}><Feather name="check-square" size={20} color={colors.primary} /><Text style={styles.statNumber}>{activeTasks.filter(task => !task.completed).length}</Text><Text style={layout.subtitle}>To do</Text></Card><Card style={styles.statCard}><Feather name="check-circle" size={20} color={colors.success} /><Text style={styles.statNumber}>{activeTasks.filter(task => task.completed).length}</Text><Text style={layout.subtitle}>Completed</Text></Card></View>{user.preview ? <Card style={styles.previewCard}><Pill text="Local preview" tone="warning" /><Text style={layout.body}>A space to try things out. Your preview stays on this device.</Text></Card> : null}<Card style={styles.heroCard}><View style={styles.sectionHeader}><Text style={styles.heroEyebrow}>YOUR NEXT STEP</Text><Feather name="sun" size={24} color={colors.primary} /></View>{nextTasks[0] ? <><Text style={styles.heroTitle}>{nextTasks[0].title}</Text><Text style={styles.heroDetail}>{dayLabel(nextTasks[0].dueDate)}</Text><Button label="Mark complete" onPress={() => void toggleTask(nextTasks[0])} /></> : <><Text style={styles.heroTitle}>You are all caught up.</Text><Text style={styles.heroDetail}>Scan a notice or create a task when you are ready.</Text><Button label="Create a task" onPress={startManual} /></>}</Card>{readyToArchive.length ? <><Text style={layout.heading}>Ready for Vault</Text>{readyToArchive.map((document) => <Card key={document.id}><Text style={layout.heading}>{document.details.title}</Text><Text style={layout.subtitle}>All tasks are complete. Review before archiving.</Text><Button label="Review and move to Vault" onPress={() => void archiveDocument(document)} /></Card>)}</> : null}<View style={styles.sectionHeader}><Text style={layout.heading}>Upcoming</Text><Pressable onPress={() => setTab('calendar')}><Text style={styles.link}>View calendar</Text></Pressable></View>{nextTasks.slice(0, 4).map((task) => <Card key={task.id}><TaskRow task={task} onToggle={() => void toggleTask(task)} /></Card>)}{!nextTasks.length ? <Card style={styles.emptyCard}><View style={styles.previewIcon}><Feather name="coffee" size={26} color={colors.primary} /></View><Text style={layout.heading}>A little breathing room.</Text><Text style={styles.emptyText}>Your upcoming tasks will find a home here. Start by scanning your first document.</Text><Button label="Scan a document" kind="secondary" onPress={() => setTab("scan")} /></Card> : null}</ScrollView>;
  const renderCalendar = () => <ScrollView contentContainerStyle={layout.content}><View><Text style={layout.title}>Calendar</Text><Text style={layout.subtitle}>Choose a day to see its planned actions.</Text></View><CalendarGrid tasks={activeTasks} selectedDate={selectedDate} onSelect={setSelectedDate} /><View style={styles.sectionHeader}><View><Text style={layout.heading}>{dayLabel(selectedDate)}</Text><Text style={layout.subtitle}>Tasks for this date</Text></View><Pill text={`${tasksForSelectedDay.length} task${tasksForSelectedDay.length === 1 ? '' : 's'}`} tone="blue" /></View>{tasksForSelectedDay.map((task) => <Card key={task.id}><TaskRow task={task} onToggle={() => void toggleTask(task)} onEdit={() => setEditTask(task)} /></Card>)}{!tasksForSelectedDay.length ? <Card><Text style={layout.body}>No tasks are scheduled for this date.</Text><Button label="Create a task" kind="secondary" onPress={startManual} /></Card> : null}</ScrollView>;
  const renderScanStart = () => <ScrollView contentContainerStyle={layout.content}><View><Text style={layout.title}>Create a plan</Text><Text style={layout.subtitle}>Scan a bill, import a notice, or start with a manual task.</Text></View><Card style={styles.scanFeature}><Feather name="file-text" size={36} color={colors.primary} /><Text style={layout.heading}>Your document stays in your control</Text><Text style={layout.subtitle}>Text recognition runs on your Android device. You review every detail before saving.</Text></Card><Button label="Scan document" onPress={() => void scanImage('camera')} /><Button label="Import photo" kind="secondary" onPress={() => void scanImage('photo')} /><Button label="Create task manually" kind="secondary" onPress={startManual} /><Card><Text style={layout.label}>Privacy default</Text><Text style={layout.body}>Scans save as reviewed details only unless you explicitly choose to retain the original image.</Text></Card></ScrollView>;
  const renderReview = () => { if (!review) return null; const identifier = review.details.accountNumber; return <ScrollView contentContainerStyle={layout.content} keyboardShouldPersistTaps="handled"><View style={styles.sectionHeader}><View><Text style={layout.title}>Review details</Text><Text style={layout.subtitle}>{review.confidence === 'high' ? 'Check the detected fields before creating tasks.' : 'Add the missing details to make this plan useful.'}</Text></View><Pressable onPress={() => setReview(null)}><Text style={styles.link}>Cancel</Text></Pressable></View>{review.sourceUri ? <Image source={{ uri: review.sourceUri }} style={styles.previewImage} /> : null}<Card><Text style={layout.label}>Document type</Text><View style={styles.choiceRow}>{(['bill', 'deadline', 'general'] as DocumentCategory[]).map((category) => <Pressable key={category} onPress={() => changeCategory(category)} style={[styles.choice, review.category === category && styles.choiceSelected]}><Text style={[styles.choiceText, review.category === category && styles.choiceTextSelected]}>{category === 'bill' ? 'Bill' : category === 'deadline' ? 'Deadline' : 'General'}</Text></Pressable>)}</View><Text style={layout.label}>Title</Text><TextInput keyboardAppearance={isDark ? "dark" : "light"} style={layout.input} value={review.details.title} onChangeText={(title) => updateReview({ title })} placeholder="Task title" placeholderTextColor={colors.textMuted} /><Text style={layout.label}>Provider or source</Text><TextInput keyboardAppearance={isDark ? "dark" : "light"} style={layout.input} value={review.details.provider} onChangeText={(provider) => updateReview({ provider })} placeholder="Meralco, school, employer…" placeholderTextColor={colors.textMuted} /><Text style={layout.label}>Amount due</Text><TextInput keyboardAppearance={isDark ? "dark" : "light"} style={layout.input} keyboardType="decimal-pad" value={review.details.amountDue?.toString() ?? ''} onChangeText={(value) => updateReview({ amountDue: value ? Number(value.replace(/,/g, '')) : undefined })} placeholder="e.g. 1520.50" placeholderTextColor={colors.textMuted} /><Text style={layout.label}>Due date</Text><TextInput keyboardAppearance={isDark ? "dark" : "light"} style={layout.input} value={review.details.dueDate ?? ''} onChangeText={(dueDate) => updateReview({ dueDate })} placeholder="YYYY-MM-DD" placeholderTextColor={colors.textMuted} /><Text style={layout.label}>Billing period</Text><TextInput keyboardAppearance={isDark ? "dark" : "light"} style={layout.input} value={review.details.billingPeriod ?? ''} onChangeText={(billingPeriod) => updateReview({ billingPeriod })} placeholder="Optional" placeholderTextColor={colors.textMuted} /><Text style={layout.label}>Account/reference number</Text><TextInput keyboardAppearance={isDark ? "dark" : "light"} style={layout.input} value={review.details.accountNumber ?? ''} onChangeText={(accountNumber) => updateReview({ accountNumber })} placeholder="Optional" placeholderTextColor={colors.textMuted} />{identifier ? <View style={styles.inline}><Pill text={maskIdentifier(identifier)} /><Text style={styles.smallNote}>Masked in the app by default.</Text></View> : null}<View style={styles.switchRow}><View style={styles.grow}><Text style={layout.body}>Retain full identifier</Text><Text style={layout.subtitle}>Only enable if you need it for payment reference.</Text></View><Switch value={review.details.retainFullIdentifier} onValueChange={(retainFullIdentifier) => updateReview({ retainFullIdentifier })} trackColor={{ true: colors.primary }} /></View></Card><Card><Text style={layout.heading}>Keep the original image?</Text><Text style={layout.subtitle}>Details only is selected by default.</Text>{(['details_only', 'image_and_details', 'discard_after_task'] as RetentionChoice[]).map((retention) => <Pressable key={retention} onPress={() => setReview({ ...review, retention })} style={[styles.retentionOption, review.retention === retention && styles.retentionSelected]}><Text style={styles.retentionTitle}>{retention === 'details_only' ? 'Save reviewed details only' : retention === 'image_and_details' ? 'Save image and reviewed details' : 'Discard image after task creation'}</Text><Text style={layout.subtitle}>{retention === 'details_only' ? 'Original image is not kept.' : retention === 'image_and_details' ? 'Stored privately in your Vault.' : 'Creates tasks but keeps no source record.'}</Text></Pressable>)}</Card><Card><Text style={layout.heading}>Suggested tasks</Text><Text style={layout.subtitle}>Edit, remove, or reorder these before saving.</Text>{reviewTasks.map((task, index) => <View key={task.id} style={styles.draftTask}><TextInput keyboardAppearance={isDark ? "dark" : "light"} style={[layout.input, styles.grow]} value={task.title} onChangeText={(title) => setReviewTasks((all) => all.map((item) => item.id === task.id ? { ...item, title } : item))} /><Pressable onPress={() => setReviewTasks((all) => all.filter((item) => item.id !== task.id))}><Feather name="x" size={22} color={colors.danger} /></Pressable><Pressable disabled={index === 0} onPress={() => setReviewTasks((all) => { const copy = [...all]; [copy[index - 1], copy[index]] = [copy[index], copy[index -1]]; return copy.map((item, position) => ({ ...item, position })); })}><Text style={styles.rowAction}>↑</Text></Pressable></View>)}<View style={styles.addTask}><TextInput keyboardAppearance={isDark ? "dark" : "light"} style={[layout.input, styles.grow]} value={newTaskTitle} onChangeText={setNewTaskTitle} placeholder="Add a task" placeholderTextColor={colors.textMuted} /><Pressable onPress={addDraftTask} style={styles.addCircle}><Feather name="plus" size={22} color={colors.onPrimary} /></Pressable></View></Card><Button label="Save plan" onPress={() => void saveReview()} /></ScrollView>; };
  const renderVault = () => <ScrollView contentContainerStyle={layout.content}><View><Text style={layout.title}>Vault</Text><Text style={layout.subtitle}>Completed records, protected by your device lock.</Text></View>{documents.filter((document) => document.status === 'archived').map((document) => { const docTasks = tasks.filter((task) => task.documentId === document.id); return <Card key={document.id}><View style={styles.sectionHeader}><View style={styles.grow}><Text style={layout.heading}>{document.details.title}</Text><Text style={layout.subtitle}>{document.details.provider || 'Saved record'} · {dayLabel(document.details.dueDate)}</Text></View><Pill text="Archived" tone="success" /></View>{document.details.amountDue !== undefined ? <Text style={styles.amount}>{peso(document.details.amountDue)}</Text> : null}<Text style={styles.smallNote}>{docTasks.filter((task) => task.completed).length}/{docTasks.length} tasks completed</Text><Button label="Restore for corrections" kind="secondary" onPress={() => void restoreDocument(document)} /></Card>; })}{!documents.some((document) => document.status === 'archived') ? <Card><Text style={layout.body}>Complete a plan, then review and archive it here for safekeeping.</Text></Card> : null}</ScrollView>;
  const renderProfile = () => <ScrollView contentContainerStyle={layout.content}><View><Text style={layout.title}>Profile</Text><Text style={layout.subtitle}>{user.email}</Text></View><Card><View style={styles.switchRow}><View style={styles.grow}><Text style={layout.heading}>Vault protection</Text><Text style={layout.subtitle}>Ask for fingerprint, face, or device credential before opening Vault.</Text></View><Switch value={biometricEnabled} onValueChange={(value) => void toggleBiometric(value)} trackColor={{ true: colors.primary }} /></View></Card><Card><Text style={layout.heading}>Your data</Text><Text style={layout.subtitle}>Export a copy or permanently remove your account and records.</Text><Button label="Export my data" kind="secondary" onPress={() => void exportData()} /><Button label="Sync now" kind="secondary" onPress={() => void syncAll()} disabled={syncing || user.preview} />{!user.preview ? <Button label="Send password reset" kind="secondary" onPress={() => void resetPassword()} /> : null}<Button label="Delete account and data" kind="danger" onPress={deleteAccount} /></Card><Button label="Sign out" kind="secondary" onPress={() => void signOut()} /><Text style={styles.privacyNote}>PicTask does not use ads, behavioral tracking, cloud AI, or automatic payments.</Text></ScrollView>;
  const renderContent = () => review ? renderReview() : tab === 'home' ? renderHome() : tab === 'calendar' ? renderCalendar() : tab === 'scan' ? renderScanStart() : tab === 'vault' ? renderVault() : renderProfile();
  return <SafeAreaView style={layout.screen} edges={['top', 'left', 'right', 'bottom']}><StatusBar barStyle={isDark ? "light-content" : "dark-content"} /><AppHeader /><AnimatedPage key={review ? "review" : tab}>{renderContent()}</AnimatedPage>{!review ? <View style={styles.tabBar}>{tabs.map((item) => <Pressable key={item.id} accessibilityRole="tab" accessibilityLabel={item.label} accessibilityState={{ selected: tab === item.id }} onPress={() => changeTab(item.id)} style={({ pressed }) => [styles.tabItem, pressed && { opacity: 0.6 }]}><View style={[styles.navIcon, tab === item.id && styles.navIconActive]}><Feather name={item.icon} size={22} color={tab === item.id ? colors.primary : colors.textMuted} /></View><Text style={[styles.tabLabel, tab === item.id && styles.tabLabelSelected]}>{item.label}</Text></Pressable>)}</View> : null}<Modal visible={Boolean(editTask)} transparent animationType={reducedMotion ? "none" : "slide"} onRequestClose={() => setEditTask(null)}>{editTask ? <View style={styles.modalBackdrop}><KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={styles.sheetKeyboard}><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={[styles.modalCard, { paddingBottom: Math.max(insets.bottom, 16) + 16 }]}><Text style={layout.heading}>Edit task</Text><Text style={layout.label}>Title</Text><TextInput keyboardAppearance={isDark ? "dark" : "light"} style={layout.input} value={editTask.title} onChangeText={(title) => setEditTask({ ...editTask, title })} /><Text style={layout.label}>Due date</Text><TextInput keyboardAppearance={isDark ? "dark" : "light"} style={layout.input} value={editTask.dueDate ?? ''} onChangeText={(dueDate) => setEditTask({ ...editTask, dueDate })} placeholder="YYYY-MM-DD" placeholderTextColor={colors.textMuted} /><Text style={layout.label}>Reminder days</Text><TextInput keyboardAppearance={isDark ? "dark" : "light"} style={layout.input} value={editTask.reminderDays.join(', ')} onChangeText={(value) => setEditTask({ ...editTask, reminderDays: value.split(',').map((item) => Number(item.trim())).filter((item) => Number.isFinite(item) && item > 0) })} placeholder="7, 3, 1" placeholderTextColor={colors.textMuted} /><Button label="Save changes" onPress={() => void saveEditedTask()} /><Button label="Delete task" kind="danger" onPress={() => void deleteTask(editTask)} /><Button label="Cancel" kind="secondary" onPress={() => setEditTask(null)} /></ScrollView></KeyboardAvoidingView></View> : null}</Modal></SafeAreaView>;
}

